class ReasoningStream:
    def __init__(self, storage_dir: str = "cache/reasoning"):
        self.storage_dir = Path(storage_dir)
        self.storage_dir.mkdir(exist_ok=True, parents=True)
        self.reasoning_cache: Dict[str, List[ReasoningEvent]] = defaultdict(list)
        self.lock = asyncio.Lock()

    async def add_reasoning(self, job_id: str, event: ReasoningEvent):
        async with self.lock:
            self.reasoning_cache[job_id].append(event)
            await self._persist_event(job_id, event)
        event_dict = {
            "event_id": event.event_id,
            "timestamp": event.timestamp,
            "agent_level": event.agent_level.value,
            "agent_id": event.agent_id,
            "context": event.context,
            "intent": event.intent,
            "decision": event.decision,
            "next_action": event.next_action,
            "evidence": event.evidence,
            "confidence": event.confidence,
            "metadata": event.metadata
        }
        await ws_manager.broadcast(job_id, {
            "type": "reasoning_event",
            "job_id": job_id,
            "event": event_dict
        })
        logger.info(f"Reasoning event added: {event.agent_level.value}/{event.agent_id}")

    async def _persist_event(self, job_id: str, event: ReasoningEvent):
        try:
            event_file = self.storage_dir / f"{job_id}_reasoning.jsonl"
            event_dict = {
                "event_id": event.event_id,
                "timestamp": event.timestamp,
                "agent_level": event.agent_level.value,
                "agent_id": event.agent_id,
                "context": event.context,
                "intent": event.intent,
                "decision": event.decision,
                "next_action": event.next_action,
                "evidence": event.evidence,
                "confidence": event.confidence,
                "metadata": event.metadata
            }
            with open(event_file, 'a', encoding='utf-8') as f:
                f.write(json.dumps(event_dict, ensure_ascii=False) + '\n')
        except Exception as e:
            logger.error(f"Failed to persist reasoning event: {e}")

    async def get_reasoning_history(self, job_id: str) -> List[ReasoningEvent]:
        async with self.lock:
            if job_id in self.reasoning_cache:
                return self.reasoning_cache[job_id]
        return await self._load_from_disk(job_id)

    async def _load_from_disk(self, job_id: str) -> List[ReasoningEvent]:
        try:
            event_file = self.storage_dir / f"{job_id}_reasoning.jsonl"
            if not event_file.exists():
                return []
            events = []
            with open(event_file, 'r', encoding='utf-8') as f:
                for line in f:
                    if line.strip():
                        event_dict = json.loads(line)
                        event = ReasoningEvent(
                            event_id=event_dict["event_id"],
                            timestamp=event_dict["timestamp"],
                            agent_level=AgentLevel(event_dict["agent_level"]),
                            agent_id=event_dict["agent_id"],
                            context=event_dict["context"],
                            intent=event_dict["intent"],
                            decision=event_dict["decision"],
                            next_action=event_dict["next_action"],
                            evidence=event_dict.get("evidence", []),
                            confidence=event_dict.get("confidence", 0.5),
                            metadata=event_dict.get("metadata", {})
                        )
                        events.append(event)
            self.reasoning_cache[job_id] = events
            return events
        except Exception as e:
            logger.error(f"Failed to load reasoning history: {e}")
            return []

    async def get_latest_reasoning(self, job_id: str, limit: int = 10) -> List[ReasoningEvent]:
        history = await self.get_reasoning_history(job_id)
        return history[-limit:] if len(history) > limit else history

class AsyncTaskStateStore:
    def __init__(self, storage_dir: str = "cache/task_states"):
        self.storage_dir = Path(storage_dir)
        self.storage_dir.mkdir(exist_ok=True, parents=True)
        self.task_states: Dict[str, TaskState] = {}
        self.plan_graphs: Dict[str, TaskGraph] = {}
        self.reasoning_entries: Dict[str, List[ReasoningEvent]] = defaultdict(list)
        self.recovery_checkpoints: Dict[str, Dict] = {}
        self.lock = asyncio.Lock()

    async def update_task(self, task_id: str, task_state: TaskState):
        async with self.lock:
            self.task_states[task_id] = task_state
            await self._persist_task_state(task_id, task_state)
        logger.info(f"Task updated: {task_id} → {task_state.status.value}")

    async def _persist_task_state(self, task_id: str, task_state: TaskState):
        try:
            state_file = self.storage_dir / f"task_{task_id}.json"
            state_dict = {
                "task_id": task_state.task_id,
                "status": task_state.status.value,
                "assigned_agent": task_state.assigned_agent,
                "start_time": task_state.start_time,
                "end_time": task_state.end_time,
                "retry_count": task_state.retry_count,
                "result": task_state.result,
                "error": task_state.error,
                "checkpoints": task_state.checkpoints
            }
            with open(state_file, 'w', encoding='utf-8') as f:
                json.dump(state_dict, f, indent=2, ensure_ascii=False)
        except Exception as e:
            logger.error(f"Failed to persist task state: {e}")

    async def create_checkpoint(self, job_id: str, checkpoint_data: Dict[str, Any]):
        async with self.lock:
            checkpoint_id = f"checkpoint_{datetime.now().timestamp()}"
            self.recovery_checkpoints[job_id] = {
                "checkpoint_id": checkpoint_id,
                "timestamp": datetime.now().isoformat(),
                "data": checkpoint_data
            }
            checkpoint_file = self.storage_dir / f"checkpoint_{job_id}.json"
            with open(checkpoint_file, 'w', encoding='utf-8') as f:
                json.dump(self.recovery_checkpoints[job_id], f, indent=2, ensure_ascii=False)
        logger.info(f"Checkpoint created: {checkpoint_id} for job {job_id}")

    async def restore_from_checkpoint(self, job_id: str) -> Optional[Dict[str, Any]]:
        async with self.lock:
            if job_id in self.recovery_checkpoints:
                return self.recovery_checkpoints[job_id]["data"]
            checkpoint_file = self.storage_dir / f"checkpoint_{job_id}.json"
            if checkpoint_file.exists():
                try:
                    with open(checkpoint_file, 'r', encoding='utf-8') as f:
                        checkpoint = json.load(f)
                    self.recovery_checkpoints[job_id] = checkpoint
                    logger.info(f"Checkpoint restored for job {job_id}")
                    return checkpoint["data"]
                except Exception as e:
                    logger.error(f"Failed to restore checkpoint: {e}")
        return None

    async def add_task_graph(self, graph_id: str, graph: TaskGraph):
        async with self.lock:
            self.plan_graphs[graph_id] = graph
        logger.info(f"Task graph added: {graph_id}")

    async def get_task_state(self, task_id: str) -> Optional[TaskState]:
        async with self.lock:
            return self.task_states.get(task_id)

    async def get_all_task_states(self, job_id: str) -> Dict[str, TaskState]:
        async with self.lock:
            return {
                tid: state for tid, state in self.task_states.items()
                if tid.startswith(job_id)
            }

class PersistentJobStore:
    def __init__(self, cache_dir: str = "cache"):
        self.cache_dir = Path(cache_dir)
        self.cache_dir.mkdir(exist_ok=True)
        self.jobs_file = self.cache_dir / "jobs.json"
        self.checkpoints_dir = self.cache_dir / "checkpoints"
        self.checkpoints_dir.mkdir(exist_ok=True)
        self.load_jobs()

    def load_jobs(self):
        global jobs_db
        if self.jobs_file.exists():
            try:
                with open(self.jobs_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                for job_id, job_data in data.items():
                    jobs_db[job_id] = JobState(**job_data)
                logger.info(f"Loaded {len(jobs_db)} jobs from persistent storage")
            except Exception as e:
                logger.error(f"Failed to load jobs: {str(e)}")

    def save_job(self, job: JobState):
        global jobs_db
        if VERIFICATION_ENABLED:
            verifier = get_verification()
            if verifier:
                job_dict = job.dict()
                if not verifier.verify_job_state(job_dict):
                    logger.error(f"❌ Job state verification failed: {job.job_id}")
                    raise ValueError("Job state violates formal specification")
                if not verifier.check_progress_invariant(job.progress):
                    logger.error(f"❌ Progress invariant violated: {job.progress}")
                    raise ValueError("Progress must be in [0, 1]")
                if not verifier.verify_sources_validity(job.sources):
                    logger.error(f"❌ Sources validation failed")
                    raise ValueError("Invalid source detected")
                logger.info(f"✅ Job {job.job_id} verified by Idris runtime")
        jobs_db[job.job_id] = job
        self.persist()

    def save_checkpoint(self, job: JobState, iteration: int):
        try:
            checkpoint_file = self.checkpoints_dir / f"{job.job_id}_{iteration}.json"
            with open(checkpoint_file, 'w', encoding='utf-8') as f:
                json.dump(job.dict(), f, indent=2, ensure_ascii=False)
            logger.info(f"Checkpoint saved for job {job.job_id} iteration {iteration}")
        except Exception as e:
            logger.error(f"Failed to save checkpoint: {str(e)}")

    def load_last_checkpoint(self, job_id: str) -> Optional[JobState]:
        try:
            checkpoint_files = list(self.checkpoints_dir.glob(f"{job_id}_*.json"))
            if not checkpoint_files:
                return None
            latest_file = max(checkpoint_files, key=lambda x: x.stat().st_mtime)
            with open(latest_file, 'r', encoding='utf-8') as f:
                data = json.load(f)
            return JobState(**data)
        except Exception as e:
            logger.error(f"Failed to load checkpoint: {str(e)}")
            return None

    def persist(self):
        try:
            data = {job_id: job.dict() for job_id, job in jobs_db.items()}
            with open(self.jobs_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            logger.error(f"Failed to persist jobs: {str(e)}")

class ConnectionManager:
    def __init__(self):
        self.active_connections: Dict[str, List[WebSocket]] = {}

    async def connect(self, job_id: str, websocket: WebSocket):
        await websocket.accept()
        if job_id not in self.active_connections:
            self.active_connections[job_id] = []
        self.active_connections[job_id].append(websocket)
        logger.info(f"WebSocket connected for job {job_id}")

    def disconnect(self, job_id: str, websocket: WebSocket):
        if job_id in self.active_connections:
            self.active_connections[job_id].remove(websocket)
            if not self.active_connections[job_id]:
                del self.active_connections[job_id]
        logger.info(f"WebSocket disconnected for job {job_id}")

    async def broadcast(self, job_id: str, message: dict):
        if job_id in self.active_connections:
            disconnected = []
            for connection in self.active_connections[job_id]:
                try:
                    await connection.send_json(message)
                except Exception as e:
                    logger.error(f"Broadcast error: {str(e)}")
                    disconnected.append(connection)
            for conn in disconnected:
                self.disconnect(job_id, conn)

