class ExaAdapter:
    def __init__(self):
        api_key = os.environ.get("EXA_API_KEY")
        if not api_key:
            raise ValueError("EXA_API_KEY not found")
        self.client = Exa(api_key=api_key)
        self.plan_limit = int(os.environ.get("EXA_PLAN_LIMIT", "100"))
        self._sem = asyncio.Semaphore(int(os.environ.get("EXA_SEARCH_CONCURRENCY", "5")))
        self._timestamps = []
        logger.info(f"Exa client initialized with plan limit: {self.plan_limit}")

    async def _rate_limit(self, qps: int = 5):
        now = time.time()
        window = 1.0
        self._timestamps = [t for t in self._timestamps if now - t <= window]
        if len(self._timestamps) >= qps:
            sleep_time = window - (now - self._timestamps[0]) + 0.01
            if sleep_time > 0:
                await asyncio.sleep(sleep_time)
        self._timestamps.append(time.time())

    async def search(self, query: str, num_results: int = 100,
                     use_autoprompt: bool = True,
                     category: Optional[str] = None,
                     exclude_domains: Optional[List[str]] = None,
                     include_domains: Optional[List[str]] = None,
                     start_published_date: Optional[str] = None,
                     end_published_date: Optional[str] = None,
                     start_crawl_date: Optional[str] = None,
                     end_crawl_date: Optional[str] = None) -> Dict[str, Any]:
        async with self._sem:
            await self._rate_limit(qps=5)
            try:
                query = sanitize_text(query)
                actual_num_results = min(num_results, self.plan_limit)
                search_params = {
                    "query": query,
                    "num_results": actual_num_results,
                    "type": "neural"
                }
                if exclude_domains:
                    search_params["exclude_domains"] = exclude_domains
                if include_domains:
                    search_params["include_domains"] = include_domains
                if category:
                    search_params["category"] = category
                if start_published_date:
                    search_params["start_published_date"] = start_published_date
                if end_published_date:
                    search_params["end_published_date"] = end_published_date
                if start_crawl_date:
                    search_params["start_crawl_date"] = start_crawl_date
                if end_crawl_date:
                    search_params["end_crawl_date"] = end_crawl_date
                results = self.client.search_and_contents(
                    **search_params,
                    text={"max_characters": 2000},
                    highlights={"num_sentences": 3, "highlights_per_url": 3}
                )
                sources = []
                for result in results.results:
                    source = {
                        "url": sanitize_text(result.url),
                        "title": sanitize_text(result.title or "Untitled"),
                        "text": sanitize_text(result.text if hasattr(result, 'text') else ""),
                        "highlights": [sanitize_text(h) for h in (result.highlights if hasattr(result, 'highlights') else [])],
                        "published_date": result.published_date if hasattr(result, 'published_date') else None,
                        "author": sanitize_text(result.author if hasattr(result, 'author') else ""),
                        "score": result.score if hasattr(result, 'score') else 0.0
                    }
                    sources.append(source)
                logger.info(f"Exa search completed: {len(sources)} results")
                return {"sources": sources, "query": query}
            except Exception as e:
                logger.error(f"Exa search error: {str(e)}")
                raise

    async def find_similar(self, url: str, num_results: int = 10,
                          exclude_source_domain: bool = False,
                          category: Optional[str] = None,
                          exclude_domains: Optional[List[str]] = None) -> Dict[str, Any]:
        async with self._sem:
            await self._rate_limit(qps=5)
            try:
                params = {
                    "url": url,
                    "num_results": min(num_results, self.plan_limit),
                    "exclude_source_domain": exclude_source_domain
                }
                if category:
                    params["category"] = category
                if exclude_domains:
                    params["exclude_domains"] = exclude_domains
                results = self.client.find_similar_and_contents(
                    **params,
                    text={"max_characters": 2000},
                    highlights={"num_sentences": 3, "highlights_per_url": 3}
                )
                sources = []
                for result in results.results:
                    source = {
                        "url": sanitize_text(result.url),
                        "title": sanitize_text(result.title or "Untitled"),
                        "text": sanitize_text(result.text if hasattr(result, 'text') else ""),
                        "highlights": [sanitize_text(h) for h in (result.highlights if hasattr(result, 'highlights') else [])],
                        "published_date": result.published_date if hasattr(result, 'published_date') else None,
                        "score": result.score if hasattr(result, 'score') else 0.0
                    }
                    sources.append(source)
                logger.info(f"Find similar completed: {len(sources)} results for {url}")
                return {"sources": sources, "original_url": url}
            except Exception as e:
                logger.error(f"Find similar error: {str(e)}")
                raise

    async def get_contents(self, ids: List[str]) -> Dict[str, Any]:
        async with self._sem:
            await self._rate_limit(qps=5)
            try:
                results = self.client.get_contents(
                    ids=ids,
                    text={"max_characters": 5000}
                )
                contents = []
                for result in results.results:
                    content = {
                        "id": result.id if hasattr(result, 'id') else "",
                        "url": sanitize_text(result.url),
                        "title": sanitize_text(result.title or "Untitled"),
                        "text": sanitize_text(result.text if hasattr(result, 'text') else ""),
                        "published_date": result.published_date if hasattr(result, 'published_date') else None,
                        "author": sanitize_text(result.author if hasattr(result, 'author') else "")
                    }
                    contents.append(content)
                logger.info(f"Get contents completed: {len(contents)} documents")
                return {"contents": contents}
            except Exception as e:
                logger.error(f"Get contents error: {str(e)}")
                raise

    async def keyword_search(self, query: str, num_results: int = 100,
                            include_domains: Optional[List[str]] = None,
                            exclude_domains: Optional[List[str]] = None,
                            start_published_date: Optional[str] = None,
                            end_published_date: Optional[str] = None) -> Dict[str, Any]:
        async with self._sem:
            await self._rate_limit(qps=5)
            try:
                query = sanitize_text(query)
                params = {
                    "query": query,
                    "num_results": min(num_results, self.plan_limit),
                    "type": "keyword"
                }
                if include_domains:
                    params["include_domains"] = include_domains
                if exclude_domains:
                    params["exclude_domains"] = exclude_domains
                if start_published_date:
                    params["start_published_date"] = start_published_date
                if end_published_date:
                    params["end_published_date"] = end_published_date
                results = self.client.search_and_contents(
                    **params,
                    text={"max_characters": 2000}
                )
                sources = []
                for result in results.results:
                    source = {
                        "url": sanitize_text(result.url),
                        "title": sanitize_text(result.title or "Untitled"),
                        "text": sanitize_text(result.text if hasattr(result, 'text') else ""),
                        "published_date": result.published_date if hasattr(result, 'published_date') else None,
                        "score": result.score if hasattr(result, 'score') else 0.0
                    }
                    sources.append(source)
                logger.info(f"Keyword search completed: {len(sources)} results")
                return {"sources": sources, "query": query, "type": "keyword"}
            except Exception as e:
                logger.error(f"Keyword search error: {str(e)}")
                raise

