class MidAgent:
    def __init__(self, agent_id: str, reasoning_stream: 'ReasoningStream',
                 task_store: 'AsyncTaskStateStore'):
        self.agent_id = agent_id
        self.reasoning_stream = reasoning_stream
        self.task_store = task_store
        self.escalation_threshold = 3
        self.max_retry_count = 3

    async def decompose_plan(self, job_id: str, plan: ResearchPlan) -> TaskGraph:
        try:
            graph_id = f"graph_{job_id}_{datetime.now().timestamp()}"
            task_graph = TaskGraph(graph_id=graph_id)
            for i, research_task in enumerate(plan.tasks):
                task_id = f"{job_id}_task_{i}"
                task_state = TaskState(
                    task_id=task_id,
                    status=TaskStatus.PENDING,
                    assigned_agent=f"subagent_{i}",
                    start_time=None,
                    end_time=None
                )
                task_graph.tasks[task_id] = task_state
                task_graph.execution_order.append(task_id)
                await self.task_store.update_task(task_id, task_state)
                if i > 0:
                    prev_task_id = f"{job_id}_task_{i-1}"
                    if prev_task_id not in task_graph.dependencies:
                        task_graph.dependencies[prev_task_id] = []
                    task_graph.dependencies[task_id] = [prev_task_id]
            await self.task_store.add_task_graph(graph_id, task_graph)
            event = ReasoningEvent(
                event_id=f"evt_{datetime.now().timestamp()}",
                timestamp=datetime.now().isoformat(),
                agent_level=AgentLevel.MIDAGENT,
                agent_id=self.agent_id,
                context=f"Plan decomposition: {plan.main_question}",
                intent="Task graph létrehozása a research plan alapján",
                decision=f"{len(plan.tasks)} task létrehozva",
                next_action="Task routing SubAgent-ekhez",
                evidence=[f"Task count: {len(plan.tasks)}", f"Graph ID: {graph_id}"],
                confidence=0.9,
                metadata={"graph_id": graph_id, "task_count": len(plan.tasks)}
            )
            await self.reasoning_stream.add_reasoning(job_id, event)
            logger.info(f"MidAgent: Plan decomposed into {len(plan.tasks)} tasks")
            return task_graph
        except Exception as e:
            logger.error(f"MidAgent decompose_plan error: {e}")
            raise

    async def route_tasks(self, job_id: str, tasks: List[ResearchTask],
                         available_subagents: List['SubAgent']) -> Dict[str, 'SubAgent']:
        try:
            task_assignments = {}
            for i, task in enumerate(tasks):
                subagent = available_subagents[i % len(available_subagents)]
                task_assignments[task.task_id] = subagent
                task_state = await self.task_store.get_task_state(task.task_id)
                if task_state:
                    task_state.assigned_agent = subagent.agent_id
                    await self.task_store.update_task(task.task_id, task_state)
            event = ReasoningEvent(
                event_id=f"evt_{datetime.now().timestamp()}",
                timestamp=datetime.now().isoformat(),
                agent_level=AgentLevel.MIDAGENT,
                agent_id=self.agent_id,
                context="Task routing",
                intent="Taskokat SubAgent-ekhez rendelni",
                decision=f"{len(tasks)} task assigned",
                next_action="SubAgent végrehajtás indítása",
                evidence=[f"Subagent count: {len(available_subagents)}"],
                confidence=0.95,
                metadata={"task_assignments": {tid: sa.agent_id for tid, sa in task_assignments.items()}}
            )
            await self.reasoning_stream.add_reasoning(job_id, event)
            logger.info(f"MidAgent: {len(tasks)} tasks routed to subagents")
            return task_assignments
        except Exception as e:
            logger.error(f"MidAgent route_tasks error: {e}")
            raise

    async def validate_outputs(self, job_id: str, results: List[MiniReport]) -> Dict[str, Any]:
        try:
            validation_results = {
                "valid_reports": [],
                "invalid_reports": [],
                "avg_confidence": 0.0,
                "needs_escalation": False
            }
            confidences = []
            for report in results:
                is_valid = (
                    len(report.content) > 50 and
                    report.confidence > 0.3 and
                    len(report.findings) > 0
                )
                if is_valid:
                    validation_results["valid_reports"].append(report)
                    confidences.append(report.confidence)
                else:
                    validation_results["invalid_reports"].append(report)
            if confidences:
                validation_results["avg_confidence"] = sum(confidences) / len(confidences)
            invalid_count = len(validation_results["invalid_reports"])
            if invalid_count >= self.escalation_threshold or validation_results["avg_confidence"] < 0.4:
                validation_results["needs_escalation"] = True
            event = ReasoningEvent(
                event_id=f"evt_{datetime.now().timestamp()}",
                timestamp=datetime.now().isoformat(),
                agent_level=AgentLevel.MIDAGENT,
                agent_id=self.agent_id,
                context="Output validation",
                intent="MiniReport eredmények minőség-ellenőrzése",
                decision=f"Valid: {len(validation_results['valid_reports'])}, Invalid: {invalid_count}",
                next_action="Escalate" if validation_results["needs_escalation"] else "Proceed with synthesis",
                evidence=[
                    f"Avg confidence: {validation_results['avg_confidence']:.2f}",
                    f"Total reports: {len(results)}"
                ],
                confidence=validation_results["avg_confidence"],
                metadata={
                    "avg_confidence": validation_results["avg_confidence"],
                    "needs_escalation": validation_results["needs_escalation"],
                    "valid_count": len(validation_results["valid_reports"]),
                    "invalid_count": len(validation_results["invalid_reports"])
                }
            )
            await self.reasoning_stream.add_reasoning(job_id, event)
            logger.info(f"MidAgent: Validated {len(results)} reports, avg confidence: {validation_results['avg_confidence']:.2f}")
            return validation_results
        except Exception as e:
            logger.error(f"MidAgent validate_outputs error: {e}")
            raise

    async def escalate_to_coordinator(self, job_id: str, issue: str, context: Dict[str, Any]):
        try:
            event = ReasoningEvent(
                event_id=f"evt_{datetime.now().timestamp()}",
                timestamp=datetime.now().isoformat(),
                agent_level=AgentLevel.MIDAGENT,
                agent_id=self.agent_id,
                context=f"Escalation required: {issue}",
                intent="Problémát jelzés a Coordinator felé",
                decision="Escalate",
                next_action="Waiting for Coordinator intervention",
                evidence=[
                    issue,
                    f"Context: {json.dumps(context, ensure_ascii=False)[:200]}"
                ],
                confidence=0.7,
                metadata={"escalation_reason": issue, "context": context}
            )
            await self.reasoning_stream.add_reasoning(job_id, event)
            logger.warning(f"MidAgent: Escalated to Coordinator: {issue}")
            return event
        except Exception as e:
            logger.error(f"MidAgent escalate_to_coordinator error: {e}")
            raise

    async def manage_task_lifecycle(self, job_id: str, task_id: str,
                                   new_status: TaskStatus, result: Optional[str] = None,
                                   error: Optional[str] = None):
        try:
            task_state = await self.task_store.get_task_state(task_id)
            if not task_state:
                logger.warning(f"Task state not found: {task_id}")
                return
            if new_status == TaskStatus.RUNNING and not task_state.start_time:
                task_state.start_time = datetime.now().isoformat()
            if new_status in [TaskStatus.COMPLETED, TaskStatus.FAILED]:
                task_state.end_time = datetime.now().isoformat()
            if result:
                task_state.result = result
            if error:
                task_state.error = error
            if new_status == TaskStatus.RETRYING:
                task_state.retry_count += 1
                if task_state.retry_count > self.max_retry_count:
                    new_status = TaskStatus.FAILED
                    await self.escalate_to_coordinator(
                        job_id,
                        f"Task {task_id} exceeded max retries ({self.max_retry_count})",
                        {"task_id": task_id, "retry_count": task_state.retry_count}
                    )
            task_state.status = new_status
            await self.task_store.update_task(task_id, task_state)
            logger.info(f"MidAgent: Task {task_id} → {new_status.value}")
        except Exception as e:
            logger.error(f"MidAgent manage_task_lifecycle error: {e}")
            raise

class CoordinatorAgent:
    def __init__(self, grok_adapter, gpt5_adapter, cerebras_adapter, exa_adapter,
