class SubAgent:
    def __init__(self, agent_id: str, grok_adapter, gpt5_adapter, cerebras_adapter, exa_adapter,
                 reasoning_stream: Optional['ReasoningStream'] = None,
                 task_store: Optional['AsyncTaskStateStore'] = None):
        self.agent_id = agent_id
        self.grok = grok_adapter
        self.gpt5 = gpt5_adapter
        self.cerebras = cerebras_adapter
        self.exa = exa_adapter
        self.reasoning_stream = reasoning_stream
        self.task_store = task_store

    async def fetch_until_satisfied(self, topic: str, seed_query: str, time_budget_s: int = 120, max_calls: int = 40) -> List[Dict]:
        seen = set()
        collected = []
        start = time.time()
        calls = 0
        query = seed_query
        while time.time() - start < time_budget_s and calls < max_calls:
            try:
                if calls % 2 == 0:
                    batch_result = await self.exa.search(
                        query=query,
                        num_results=100
                    )
                else:
                    batch_result = await self.exa.keyword_search(
                        query=query,
                        num_results=100
                    )
                batch = batch_result.get("sources", [])
                calls += 1
                new = 0
                for src in batch:
                    url = (src.get("url") or "").strip()
                    if url and url not in seen:
                        seen.add(url)
                        collected.append(src)
                        new += 1
                if new > 0 and calls % 5 == 0 and len(collected) < 2000:
                    try:
                        similar_result = await self.exa.find_similar(
                            url=url,
                            num_results=100,
                            exclude_source_domain=True
                        )
                        similar_sources = similar_result.get("sources", [])
                        for sim_src in similar_sources:
                            sim_url = (sim_src.get("url") or "").strip()
                            if sim_url and sim_url not in seen:
                                seen.add(sim_url)
                                collected.append(sim_src)
                                new += 1
                    except:
                        pass
                novelty = new / max(len(batch), 1)
                if novelty < 0.25:
                    query = f"{topic} details {calls}"
                else:
                    query = f"{topic} analysis {calls}"
                if len(collected) >= 3000:
                    break
            except Exception as e:
                break
        logger.info(f"Fetch until satisfied: {len(collected)} sources collected in {calls} calls")
        return collected

    async def execute_task(self, task: ResearchTask, sources: Optional[List[Dict]] = None) -> MiniReport:
        try:
            if not sources:
                sources = await self.fetch_until_satisfied(
                    topic=task.description,
                    seed_query=task.description,
                    time_budget_s=120,
                    max_calls=40
                )
            sources_context = "\n\n".join([
                f"Forrás {i+1}: {s.get('title', 'N/A')}\n{s.get('text', '')[:300]}"
                for i, s in enumerate(sources[:10])
            ])
            result = await self.cerebras.generate_synthesis(
                prompt=f"{task.description}\n\nForrások:\n{sources_context}",
                model="gpt-oss-120b"
            )
            content = result
            findings = content.split(".")[:5]
            confidence = 0.8
            return MiniReport(
                agent_id=self.agent_id,
                task_id=task.task_id,
                timestamp=datetime.now().isoformat(),
                content=content,
                findings=findings if isinstance(findings, list) else [findings],
                confidence=confidence,
                sources_used=[s.get('url', '') for s in sources[:5]],
                metadata={"model": "cerebras", "sources_collected": len(sources)}
            )
        except Exception as e:
            return MiniReport(
                agent_id=self.agent_id,
                task_id=task.task_id,
                timestamp=datetime.now().isoformat(),
                content=f"Hiba: {str(e)}",
                findings=[],
                confidence=0.0
            )

class EnhancedResearchMode:
    def __init__(self, orchestrator):
        self.orchestrator = orchestrator
        self.coordinator = orchestrator.coordinator

    async def execute(self, job):
        logger_mode = logging.getLogger("EnhancedMode")
        try:
            job.status = JobStatus.RUNNING
            job.progress = 0.05
            understanding = await self.coordinator.understand_request(job.job_id, job.prompt)
            job.progress = 0.15
            plan = await self.coordinator.create_research_plan(understanding)
            job.progress = 0.25
            task_graph = await self.orchestrator.midagent.decompose_plan(job.job_id, plan)
            job.progress = 0.3
            external_sources = []
            if plan.needs_external_search:
                for query in plan.search_queries[:3]:
                    try:
                        search_result = await self.orchestrator.exa.search(
                            query=query, num_results=50, exclude_domains=[]
                        )
                        external_sources.extend(search_result.get('sources', []))
                    except:
                        pass
            subagents = [
                SubAgent(
                    agent_id=f"subagent_{i+1}",
                    grok_adapter=self.orchestrator.grok,
                    gpt5_adapter=self.orchestrator.gpt5,
                    cerebras_adapter=self.orchestrator.cerebras,
                    exa_adapter=self.orchestrator.exa,
                    reasoning_stream=self.orchestrator.reasoning_stream,
                    task_store=self.orchestrator.task_store
                )
                for i in range(len(plan.tasks))
            ]
            task_assignments = await self.orchestrator.midagent.route_tasks(
                job.job_id, plan.tasks, subagents
            )
            mini_reports: List[MiniReport] = []
            for i, task in enumerate(plan.tasks):
                subagent = task_assignments.get(task.task_id, subagents[0])
                await self.orchestrator.midagent.manage_task_lifecycle(
                    job.job_id, task.task_id, TaskStatus.RUNNING
                )
                mini_report = await subagent.execute_task(task, external_sources)
                mini_reports.append(mini_report)
                task_status = TaskStatus.COMPLETED if mini_report.confidence > 0.3 else TaskStatus.FAILED
                await self.orchestrator.midagent.manage_task_lifecycle(
                    job.job_id, task.task_id, task_status, result=mini_report.content
                )
            validation_results = await self.orchestrator.midagent.validate_outputs(
                job.job_id, mini_reports
            )
            if validation_results["needs_escalation"]:
                await self.orchestrator.midagent.escalate_to_coordinator(
                    job.job_id,
                    "Low confidence in mini reports",
                    validation_results
                )
            job.progress = 0.85
            mini_reports_context = "\n\n".join([
                f"SubAgent {r.agent_id} jelentése:\n{r.content[:800]}"
                for r in mini_reports
            ])
            final_synthesis_prompt = f"""Készíts végső kutatási jelentést.

Kérdés: {job.prompt}

SubAgent mini jelentések:

{mini_reports_context}

Források száma: {len(external_sources)}

Készíts részletes markdown jelentést.

"""
            final_synthesis = await self.orchestrator.cerebras.generate_synthesis(
                prompt=final_synthesis_prompt,
                model="gpt-oss-120b",
                max_tokens=65000
            )
            job.report = final_synthesis if final_synthesis else "Jelentés készítése sikertelen"
            job.status = JobStatus.COMPLETED
            job.progress = 1.0
            logger_mode.info(f"Enhanced mode completed for job {job.job_id}")
        except Exception as e:
            logger_mode.error(f"Enhanced mode error: {e}")
            job.status = JobStatus.FAILED
            job.error = str(e)

class ResearchOrchestrator:
    def __init__(self):
        self.exa = ExaAdapter()
        self.grok = GrokAdapter()
        self.gpt5 = GPT5Adapter()
        self.cerebras = CerebrasAdapter()
        self.reasoning_stream = ReasoningStream()
        self.task_store = AsyncTaskStateStore()
        self.coordinator = CoordinatorAgent(
            grok_adapter=self.grok,
            gpt5_adapter=self.gpt5,
            cerebras_adapter=self.cerebras,
            exa_adapter=self.exa,
            reasoning_stream=self.reasoning_stream
        )
        self.midagent = MidAgent(
            agent_id="midagent_main",
            reasoning_stream=self.reasoning_stream,
            task_store=self.task_store
        )

    async def update_and_broadcast(self, job: JobState, progress: Optional[float] = None,
                                  current_step: Optional[str] = None, status: Optional[JobStatus] = None):
        if progress is not None:
            job.progress = progress
        if current_step is not None:
            job.current_step = current_step
        if status is not None:
            job.status = status
        job.updated_at = datetime.now().isoformat()
        job_store.save_job(job)
        await ws_manager.broadcast(job.job_id, {
            "type": "status_update",
            "job_id": job.job_id,
            "status": job.status.value,
            "progress": job.progress,
            "current_step": job.current_step
        })

    async def execute_simple_mode(self, job: JobState) -> None:
        try:
            job.status = JobStatus.RUNNING
            job.current_step = "Kezdeti keresés"
            job.progress = 0.1
            seen_urls = set()
            sources = []
            for batch_num in range(10):
                try:
                    search_params = {
                        "query": job.prompt,
                        "num_results": 100,
                        "exclude_domains": []
                    }
                    if hasattr(job, 'start_published_date') and job.start_published_date:
                        search_params["start_published_date"] = job.start_published_date
                    if hasattr(job, 'end_published_date') and job.end_published_date:
                        search_params["end_published_date"] = job.end_published_date
                    if hasattr(job, 'search_category') and job.search_category:
                        search_params["category"] = job.search_category
                    if hasattr(job, 'include_domains') and job.include_domains:
                        search_params["include_domains"] = job.include_domains
                    search_results = await self.exa.search(**search_params)
                    batch_sources = search_results["sources"]
                    new_count = 0
                    for src in batch_sources:
                        url = src.get("url", "").strip()
                        if url and url not in seen_urls:
                            seen_urls.add(url)
                            sources.append(src)
                            new_count += 1
                    if new_count > 0 and batch_num % 3 == 0 and len(sources) < 600:
                        try:
                            top_url = batch_sources[0].get("url")
                            if top_url:
                                similar_result = await self.exa.find_similar(
                                    url=top_url,
                                    num_results=20,
                                    exclude_source_domain=True
                                )
                                for sim_src in similar_result.get("sources", []):
                                    sim_url = sim_src.get("url", "").strip()
                                    if sim_url and sim_url not in seen_urls:
                                        seen_urls.add(sim_url)
                                        sources.append(sim_src)
                        except:
                            pass
                    novelty = new_count / max(len(batch_sources), 1)
                    if novelty < 0.2 or len(sources) >= 800:
                        break
                except Exception as e:
                    break
            for src in sources:
                reliability = "high" if src.get("score", 0) > 0.7 else ("medium" if src.get("score", 0) > 0.4 else "low")
                authority = min(src.get("score", 0.5), 1.0)
                source_obj = Source(
                    url=src["url"],
                    title=src["title"],
                    date=src.get("published_date"),
                    authority_score=authority,
                    reliability=reliability,
                    excerpt=src.get("text", "")[:300] + "..." if src.get("text") else "",
                    verified=False
                )
                job.sources.append(source_obj)
            job.progress = 0.6
            job.current_step = "Szintézis generálása"
            top_sources = sources[:10]
            context = "\n\n".join([
                f"Forrás: {s['title']}\n{s.get('text', '')[:800]}"
                for s in top_sources
            ])
            synthesis_prompt = f"""Készíts átfogó választ.

Kérdés: {job.prompt}

Kontextus:

{context}

Részletes markdown jelentés.

"""
            synthesis = await self.cerebras.generate_synthesis(
                prompt=synthesis_prompt,
                model="gpt-oss-120b",
                max_tokens=65000
            )
            final_report = f"""# Kutatási Jelentés

**Kérdés:** {job.prompt}

**Források száma:** {len(sources)}

---

{synthesis}

---

## Források

"""
            for i, src in enumerate(top_sources[:10], 1):
                final_report += f"\n{i}. [{src['title']}]({src['url']})"
            job.report = final_report
            job.status = JobStatus.COMPLETED
            job.progress = 1.0
            job.updated_at = datetime.now().isoformat()
        except Exception as e:
            logger.error(f"Simple mode error: {str(e)}")
            job.status = JobStatus.FAILED
            job.error = str(e)
            job.updated_at = datetime.now().isoformat()

    async def execute_research_mode(self, job: JobState) -> None:
        try:
            enhanced = EnhancedResearchMode(self)
            await enhanced.execute(job)
        except Exception as e:
            logger.error(f"Research mode error: {str(e)}")
            job.status = JobStatus.FAILED
            job.error = str(e)

    async def execute_autonomous_mode(self, job: JobState) -> None:
        try:
            enhanced = EnhancedResearchMode(self)
            await enhanced.execute(job)
        except Exception as e:
            logger.error(f"Autonomous mode error: {str(e)}")
            job.status = JobStatus.FAILED
            job.error = str(e)

