@app.get("/report/{job_id}")
async def get_report(job_id: str):
    if job_id not in jobs_db:
        raise HTTPException(status_code=404, detail="Job not found")
    job = jobs_db[job_id]
    if job.status != JobStatus.COMPLETED:
        raise HTTPException(status_code=400, detail="Report not ready")
    try:
        reasoning_history = await orchestrator.reasoning_stream.get_reasoning_history(job_id)
        reasoning_metrics = {
            "total_reasoning_cycles": len(reasoning_history),
            "coordinator_decisions": len([e for e in reasoning_history if e.agent_level.value == "coordinator"]),
            "midagent_actions": len([e for e in reasoning_history if e.agent_level.value == "midagent"]),
            "subagent_executions": len([e for e in reasoning_history if e.agent_level.value == "subagent"]),
            "avg_confidence": sum([e.confidence for e in reasoning_history]) / max(len(reasoning_history), 1) if reasoning_history else 0.0,
            "low_confidence_count": len([e for e in reasoning_history if e.confidence < 0.5])
        }
    except Exception as e:
        logger.warning(f"Failed to get reasoning metrics: {e}")
        reasoning_metrics = {
            "total_reasoning_cycles": 0,
            "coordinator_decisions": 0,
            "midagent_actions": 0,
            "subagent_executions": 0,
            "avg_confidence": 0.0,
            "low_confidence_count": 0
        }
    try:
        task_states = await orchestrator.task_store.get_all_task_states(job_id)
        if task_states:
            durations = []
            for task_id, state in task_states.items():
                if state.start_time and state.end_time:
                    try:
                        start = datetime.fromisoformat(state.start_time)
                        end = datetime.fromisoformat(state.end_time)
                        duration = (end - start).total_seconds()
                        durations.append(duration)
                    except:
                        pass
            execution_stats = {
                "total_tasks": len(task_states),
                "completed_tasks": len([s for s in task_states.values() if s.status.value == "completed"]),
                "failed_tasks": len([s for s in task_states.values() if s.status.value == "failed"]),
                "avg_task_duration": sum(durations) / len(durations) if durations else 0,
                "retry_count": sum([s.retry_count for s in task_states.values()])
            }
        else:
            execution_stats = {
                "total_tasks": 0,
                "completed_tasks": 0,
                "failed_tasks": 0,
                "avg_task_duration": 0,
                "retry_count": 0
            }
    except Exception as e:
        logger.warning(f"Failed to get execution stats: {e}")
        execution_stats = {
            "total_tasks": 0,
            "completed_tasks": 0,
            "failed_tasks": 0,
            "avg_task_duration": 0,
            "retry_count": 0
        }
    sources = job.sources
    unique_domains = len(set([urlparse(s.url).netloc for s in sources if s.url]))
    knowledge_metrics = {
        "total_sources": len(sources),
        "unique_domains": unique_domains,
        "source_diversity": unique_domains / max(len(sources), 1) if sources else 0,
        "verified_sources": len([s for s in sources if s.verified]),
        "high_reliability_sources": len([s for s in sources if s.reliability == "high"])
    }
    enhanced_report = job.report
    if reasoning_metrics["total_reasoning_cycles"] > 0 or execution_stats["total_tasks"] > 0:
        metrics_section = f"""

---

## 📊 Deep Research Metrikák

### Gondolkodási Statisztikák

- Összes reasoning ciklus: {reasoning_metrics['total_reasoning_cycles']}
- Coordinator döntések: {reasoning_metrics['coordinator_decisions']}
- MidAgent műveletek: {reasoning_metrics['midagent_actions']}
- SubAgent végrehajtások: {reasoning_metrics['subagent_executions']}
- Átlagos megbízhatóság: {reasoning_metrics['avg_confidence']:.1%}
- Alacsony megbízhatóságú döntések: {reasoning_metrics['low_confidence_count']}

### Végrehajtási Statisztikák

- Összes task: {execution_stats.get('total_tasks', 0)}
- Befejezett: {execution_stats.get('completed_tasks', 0)}
- Sikertelen: {execution_stats.get('failed_tasks', 0)}
- Átlagos task időtartam: {execution_stats.get('avg_task_duration', 0):.2f}s
- Újrapróbálkozások: {execution_stats.get('retry_count', 0)}

### Tudásbázis Metrikák

- Források száma: {knowledge_metrics['total_sources']}
- Egyedi domainek: {knowledge_metrics['unique_domains']}
- Forrás diverzitás: {knowledge_metrics['source_diversity']:.1%}
- Verifikált források: {knowledge_metrics['verified_sources']}
- Magas megbízhatóságú források: {knowledge_metrics['high_reliability_sources']}

"""
        enhanced_report = enhanced_report + metrics_section
    return {
        "job_id": job.job_id,
        "report": enhanced_report,
        "sources_count": len(job.sources),
        "reasoning_metrics": reasoning_metrics,
        "execution_stats": execution_stats,
        "knowledge_metrics": knowledge_metrics
    }

